const engineer = {
  name: "Parth",
  role: "Cloud & Infra"
};

const manager = {
  name: "Rajesh",
  role: "Lead"
};

function introduce(greeting) {
  console.log(`${greeting}, I'm ${this.name}, ${this.role}`);
}

introduce.call(engineer, "Hello");
