"use strict";

const pipeline = {
  stage: "deploy",
  run: function() {
    console.log("1:", this.stage);

    const setup = () => {
      console.log("2:", this.stage);

      function validate() {
        console.log("3:", this.stage);
      }
      validate();
    };
    setup();
  }
