pipeline.run();

const api = {
  version: "v1",
  create: function() {
    console.log("A:", this.version);

    return {
      version: "v2",
      deploy: function() {
        console.log("B:", this.version);

        const monitor = () => {
          console.log("C:", this.version);

          setTimeout(function() {
            console.log("D:", this.version);
          }, 100);

          setTimeout(() => {
            console.log("E:", this.version);
          }, 200);
        };
        monitor();
      }
    };
  }
};

const service = api.create();
service.deploy();   // non-strict mode

